   131→fun pow10_u64(exp: u8): u64 {
   132→    if (exp == 0) 1
   133→    else if (exp == 1) 10
   134→    else if (exp == 2) 100
   135→    else if (exp == 3) 1_000
   136→    else if (exp == 4) 10_000
