   212→    };
   213→
   214→    // updating the timestamp here clearing the very first segment that we filled last time
   215→    // hence the outflow limiter wouldn't throw an error because it satisfy the limit
   216→    mock_timestamp = mock_timestamp + segment_duration;
   217→    limiter.add_outflow(mock_timestamp, 100);
   218→    limiter.reduce_outflow( mock_timestamp, 100);
   219→    limiter.add_outflow(mock_timestamp, 100);
   220→}
