// =============== Public Getter Functions ==============

public fun assert_emode_group_exists<MarketType>(self: &Market<MarketType>, group: u8) {
    self.emode_group_registry.ensure_group_exists(group)
}

public fun emode_registry<MarketType>(self: &Market<MarketType>): &EModeGroupRegistry {
    &self.emode_group_registry
}

public(package) fun supported_assets<MarketType>(self: &Market<MarketType>): vector<TypeName> {
    self.assets.keys()
}

public(package) fun has_circuit_break_triggered<MarketType>(self: &Market<MarketType>): bool {
    *dynamic_field::borrow(&self.id, CircuitBreakKey {})
}

public(package) fun market_config<MarketType>(self: &Market<MarketType>): &MarketConfiguration {
    dynamic_field::borrow(&self.id, MarketConfigurationKey {})
}

public(package) fun adl_registry<MarketType>(self: &Market<MarketType>): &AutoDeleverageRegistry {
    dynamic_field::borrow<ADLRegistryKey, AutoDeleverageRegistry>(&self.id, ADLRegistryKey {})
}

public(package) fun asset_by_type<MarketType>(
    self: &Market<MarketType>,
    name: TypeName,
): &Asset<MarketType> {
    self.assets.load_by_type<Asset<MarketType>>(name)
}

public(package) fun reserve_by_type<MarketType>(
    self: &Market<MarketType>,
    name: TypeName,
): &Reserve<MarketType> {
    self.reserves.load_by_type<Reserve<MarketType>>(name)
}

public fun exchange_rate<MarketType>(self: &Market<MarketType>, coin_type: TypeName): Decimal {
    self.reserve_by_type<MarketType>(coin_type).exchange_rate()
}

public fun borrow_obligation<MarketType>(
    self: &Market<MarketType>,
    obligation_id: ID,
): &Obligation<MarketType> {
    self.obligations.borrow(obligation_id)
}

// =============== Admin Functions ==============
public(package) fun market_asset_borrow_mut<MarketType, CoinType>(
    self: &mut Market<MarketType>,
): &mut Asset<MarketType> {
    self.assets.load_mut_by_type(type_name::with_defining_ids<CoinType>())
}

public(package) fun set_ema_spot_tolerance<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    tolerance_bps: u64
) {
    assert!(tolerance_bps < DEFAULT_EMA_SPOT_DIFF_DENOMINATOR, error::invalid_params_error());

    let tolerance = math::float::from_quotient(tolerance_bps, DEFAULT_EMA_SPOT_DIFF_DENOMINATOR);

    let t = self.ema_spot_tolerance.load_mut_by_type(type_name::with_defining_ids<CoinType>());
    *t = tolerance;
}

/// Take revenue from market reserves
public(package) fun take_revenue<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    amount: u64,
    ctx: &mut TxContext,
): Coin<CoinType> {
    let reserve = self.reserves.load_mut_by_type(type_name::with_defining_ids<CoinType>());
    let balance = reserve::take_revenue<MarketType, CoinType>(reserve, amount);
    coin::from_balance(balance, ctx)
}

// ================== Internal Update Functions ================
public(package) fun onboard_new_asset<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    interest_model: InterestModel,
    borrow: AssetConfig,
    now: u64,
    ctx: &mut TxContext,
) {
    assert!(!self.assets.supports<Asset<MarketType>, CoinType>(), error::asset_already_onboarded());

    let new_asset = asset::new<MarketType>(interest_model, borrow, ctx);
    self.assets.store<Asset<MarketType>, CoinType>(new_asset);

    let reserve = reserve::new<MarketType, CoinType>(ctx, now);
    self.reserves.store<Reserve<MarketType>, CoinType>(reserve);

    self.ema_spot_tolerance.store<Decimal, CoinType>(float::from_quotient(DEFAULT_EMA_SPOT_DIFF_TOLERANCE_BPS, DEFAULT_EMA_SPOT_DIFF_DENOMINATOR));

